"""Loads the site corpus (generated by `npm run assistant:corpus`) and the owner's notes."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from pathlib import Path

_COMMENT = re.compile(r"<!--.*?-->", re.S)
_WORD = re.compile(r"[a-z0-9₹]+")


@dataclass(frozen=True)
class Link:
    path: str
    label: str


@dataclass(frozen=True)
class Section:
    title: str
    body: str
    path: str | None  # page the section comes from, when known


@dataclass(frozen=True)
class Corpus:
    name: str
    links: tuple[Link, ...]
    knowledge: str
    notes: str

    @property
    def paths(self) -> set[str]:
        return {l.path for l in self.links}

    def sections(self) -> list[Section]:
        """Splits the knowledge (and notes) into ### / ## sections for offline lookup."""
        out: list[Section] = []
        text = self.knowledge + ("\n\n## Owner notes\n" + self.notes if self.notes else "")
        page: str | None = None
        for block in re.split(r"\n(?=#{2,3} )", text):
            head, _, body = block.partition("\n")
            title = head.lstrip("#").strip()
            src = re.search(r"\(source: (/[\w/-]*)\)", head)
            if head.startswith("## "):
                page = src.group(1) if src else None
            path = re.search(r" — (/[\w/-]+)$", title)
            out.append(
                Section(
                    title=re.sub(r" — /[\w/-]+$| \(source: [^)]*\)", "", title),
                    body=body.strip(),
                    path=path.group(1) if path else (page or "/about"),
                )
            )
        return [s for s in out if s.body]


def strip_comments(text: str) -> str:
    return _COMMENT.sub("", text).strip()


def load_corpus(corpus_path: Path, notes_path: Path) -> Corpus:
    data = json.loads(corpus_path.read_text(encoding="utf-8"))
    notes = strip_comments(notes_path.read_text(encoding="utf-8")) if notes_path.exists() else ""
    return Corpus(
        name=data["name"],
        links=tuple(Link(l["path"], l["label"]) for l in data["links"]),
        knowledge=data["knowledge"],
        notes=notes,
    )


def words(text: str) -> list[str]:
    return _WORD.findall(text.lower())
